from collections import deque

def max_window(a, k):
    q, out = deque(), []
    for i, x in enumerate(a):
        while q and a[q[-1]] <= x: q.pop()
        q.append(i)
        if q[0] <= i - k: q.popleft()
        if i >= k - 1: out.append(a[q[0]])
    return out

def find(x, p):
    if p[x] != x:
        p[x] = find(p[x], p)
    return p[x]

def union(a, b, p, sz):
    ra, rb = find(a, p), find(b, p)
    if ra == rb: return
    if sz[ra] < sz[rb]: ra, rb = rb, ra
    p[rb], sz[ra] = ra, sz[ra] + sz[rb]
